<?php
if(!defined('ABSPATH'))exit(1);
$tester=new WordPressNewsBot\SourceConnectionTester();$errors=[];
foreach([['https://example.com/rss.xml?category=fixture','RSS 2.0',20],['https://example.com/atom.xml','Atom',20],['https://example.com/rdf.xml','RSS 1.0/RDF',1],['https://example.com/generic.xml','RSS 2.0',20],['https://www.example.com/redirect','RSS 2.0',20]]as[$url,$type,$count]){try{$result=$tester->test($url,['example.com']);if($result['feed_type']!==$type||$result['item_count']!==$count)$errors[]='success:'.$url;}catch(Throwable$e){$errors[]='success:'.$url.':'.get_class($e).':'.($e instanceof WordPressNewsBot\SourceTestException?$e->resultCode:'exception');}}
foreach([['https://example.com/empty','body_empty'],['https://example.com/broken','xml_invalid'],['https://example.com/blocked','content_type_invalid'],['https://example.com/rate-limited','http_status_invalid'],['https://example.com/server-error','http_status_invalid'],['https://example.com/private-redirect','redirect_blocked']]as[$url,$code]){try{$tester->test($url,['example.com']);$errors[]='failure-not-raised:'.$url;}catch(WordPressNewsBot\SourceTestException$e){if($e->resultCode!==$code)$errors[]='failure-code:'.$url.':'.$e->resultCode;}}
if($errors){fwrite(STDERR,implode("\n",$errors)."\n");exit(1);}echo json_encode(['success_cases'=>5,'failure_cases'=>6,'copyrighted_content'=>false])."\n";
